		findings.push({ code: "fuel-consumption-estimator-using-vessel-2/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "fuel-consumption-estimator-using-vessel-2/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "fuel-consumption-estimator-using-vessel-2/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

